package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
)

// thresholdsFile 是低库存阈值配置相对仓库根的位置（见 config/README.md）。
const thresholdsFile = "config/thresholds.json"

// loadThresholds 读取 config/thresholds.json，返回「仓库名 → 阈值」。
// 文件不存在、读不了、或不是这样的 JSON 对象时返回 nil，调用方据此回退默认值。
//
// 刻意不做缓存：每次调用都重新读盘，运维改完文件下一次判定即生效，
// 不需要重新构建或重启。
func loadThresholds() map[string]int {
	path := findThresholdsFile()
	if path == "" {
		return nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// findThresholdsFile 从当前工作目录逐级向上找第一个 config/thresholds.json，
// 找不到返回空串。向上找是因为 `go test ./...` 以包目录为工作目录，
// 而配置住在仓库根的 config/ 下。
func findThresholdsFile() string {
	dir, err := os.Getwd()
	if err != nil {
		return ""
	}
	for {
		candidate := filepath.Join(dir, thresholdsFile)
		if info, err := os.Stat(candidate); err == nil && !info.IsDir() {
			return candidate
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return ""
		}
		dir = parent
	}
}

