package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// useTempThresholds 在一个临时目录下写 config/thresholds.json，并把工作目录切过去，
// 让 LowStockThreshold 走真实的「向上查找 + 读文件」路径，而不是碰仓库里的配置。
// 返回配置文件路径，方便测试中途改写它。t.Chdir 会在用例结束时恢复工作目录。
func useTempThresholds(t *testing.T, content string) string {
	t.Helper()
	dir := t.TempDir()
	path := filepath.Join(dir, "config", "thresholds.json")
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
	t.Chdir(dir)
	return path
}

func TestConfiguredWarehouseUsesItsThreshold(t *testing.T) {
	useTempThresholds(t, `{"xian": 10}`)

	if got := LowStockThreshold("xian"); got != 10 {
		t.Fatalf("LowStockThreshold(xian) = %d, 期望配置值 10", got)
	}
	if !IsLowStock("xian", 9) {
		t.Fatal("9 低于配置阈值 10，应当算低库存")
	}
	if IsLowStock("xian", 10) {
		t.Fatal("10 等于配置阈值，不算低库存（严格小于）")
	}
}

func TestWarehouseAbsentFromConfigFallsBackToDefault(t *testing.T) {
	useTempThresholds(t, `{"xian": 10}`)

	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("LowStockThreshold(chengdu) = %d, 期望默认值 %d",
			got, DefaultLowStockThreshold)
	}
}

func TestMissingEmptyOrCorruptConfigFallsBackToDefault(t *testing.T) {
	cases := []struct {
		name    string
		content string
	}{
		{"空对象", `{}`},
		{"JSON 损坏", `{"xian": `},
		{"值类型不符", `{"xian": "high"}`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			useTempThresholds(t, tc.content)
			if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
				t.Fatalf("LowStockThreshold(xian) = %d, 期望默认值 %d",
					got, DefaultLowStockThreshold)
			}
		})
	}

	t.Run("文件缺失", func(t *testing.T) {
		t.Chdir(t.TempDir())
		if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
			t.Fatalf("LowStockThreshold(xian) = %d, 期望默认值 %d",
				got, DefaultLowStockThreshold)
		}
	})
}

// 同一个进程内改写文件、不重启不重编译，下一次调用就要读到新值——这是「改配置不用重新构建」的证明。
func TestConfigChangeTakesEffectWithoutRebuild(t *testing.T) {
	path := useTempThresholds(t, `{"xian": 10}`)

	if got := LowStockThreshold("xian"); got != 10 {
		t.Fatalf("改文件前 LowStockThreshold(xian) = %d, 期望 10", got)
	}

	if err := os.WriteFile(path, []byte(`{"xian": 3}`), 0o644); err != nil {
		t.Fatal(err)
	}
	if got := LowStockThreshold("xian"); got != 3 {
		t.Fatalf("改文件后 LowStockThreshold(xian) = %d, 期望 3", got)
	}
}

// 一次性探针：在真实进程里读 cwd 下的 config/thresholds.json，验证按仓库阈值与改文件即生效。
package main

import (
	"fmt"
	"os"

	"example.com/inventory"
)

func write(content string) {
	if err := os.WriteFile("config/thresholds.json", []byte(content), 0o644); err != nil {
		panic(err)
	}
}

func main() {
	fmt.Printf("v1 {\"xian\":10}: LowStockThreshold(xian)=%d IsLowStock(xian,9)=%v\n",
		inventory.LowStockThreshold("xian"), inventory.IsLowStock("xian", 9))

	write(`{"xian": 3}`)
	fmt.Printf("v2 {\"xian\":3}:  LowStockThreshold(xian)=%d IsLowStock(xian,9)=%v\n",
		inventory.LowStockThreshold("xian"), inventory.IsLowStock("xian", 9))

	write(`{}`)
	fmt.Printf("empty {}:      LowStockThreshold(xian)=%d (default %d)\n",
		inventory.LowStockThreshold("xian"), inventory.DefaultLowStockThreshold)

	write(`{"xian": 10}`)
	fmt.Printf("v3 {\"xian\":10}: LowStockThreshold(xian)=%d\n", inventory.LowStockThreshold("xian"))
}

